<script setup lang="ts">
const props=defineProps<{warehouseId:number}>()
const {t}=useI18n(),staff=useStaffStore(),{bizErrorMessage}=useBizError()
const state=ref<any>(null),published=ref<any>(null),loading=ref(false),error=ref('')
let generation=0
const load=async()=>{const seq=++generation;loading.value=true;error.value='';published.value=null;const root='/api/warehouse/warehouse/'+props.warehouseId+'/layout';const result=await httpRequest<any>(root,{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq!==generation)return;state.value=result;if(result?.published_version){const version=await httpRequest<any>(root+'/versions/'+result.published_version,{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation)published.value=version}if(seq===generation)loading.value=false}
const rows=computed(()=>{const draft=state.value?.draft?.floors||[],live=published.value?.layout?.floors||[];return [...new Set([...live.map((f:any)=>f.id),...draft.map((f:any)=>f.id)])].map(id=>{const current=live.find((f:any)=>f.id===id),pending=draft.find((f:any)=>f.id===id),value=current||pending;const racks=value.objects.filter((o:any)=>o.type==='rack');return {...value,live:!!current,changed:JSON.stringify(current)!==JSON.stringify(pending),racks:racks.length,locations:new Set(racks.flatMap((r:any)=>r.location_ids||[])).size}})})
const columns=computed(()=>[{key:'name',label:t('layout.floors')},{key:'version',label:t('warehouse.ui.plan-version')},{key:'status',label:t('common.fields.status')},{key:'racks',label:t('layout.kind.rack'),type:'qty' as const,keepZero:true},{key:'locations',label:t('nav.location'),type:'qty' as const,keepZero:true},{key:'published',label:t('layout.publish')},{key:'actions',label:t('common.fields.action'),align:'right' as const}])
watch(()=>props.warehouseId,load,{immediate:true});onBeforeUnmount(()=>generation++)
</script>
<template><WCard :title="t('layout.title')" flush><template #actions><WButton v-if="staff.hasPermission('warehouse_edit')" size="sm" :to="'/warehouse/layout/'+warehouseId">{{t('button.edit')}}</WButton></template><WAlert v-if="error" tone="block" :title="error"/><WTable :rows="rows" :columns="columns" :loading="loading" inset><template #cell-name="{row}"><strong class="floor-name">{{row.name}}</strong><small>{{row.width}} × {{row.height}} m</small></template><template #cell-version="{row}"><strong>{{row.live?'v'+state.published_version:'—'}}</strong><small v-if="row.changed">{{t('layout.revision',{n:state.revision})}}</small></template><template #cell-status="{row}"><WStatus muted :tone="row.live?'ok':'none'">{{row.live?t('warehouse.ui.plan-live'):t('layout.draft')}}</WStatus><small v-if="row.changed">{{t('warehouse.ui.plan-changed')}}</small></template><template #cell-published="{row}">{{row.live?$dayjs(published.published_at,'MM/DD HH:mm',warehouseId):'—'}}</template><template #cell-actions="{row}"><NuxtLink class="w-plan-link" :to="{path:'/warehouse/layout/'+warehouseId,query:row.live?{version:state.published_version,floor:row.id}:{floor:row.id}}">{{t('layout.view-map')}} →</NuxtLink></template></WTable></WCard></template>
<style scoped>
.floor-name{font-size:14px;font-weight:600;line-height:22px}small{display:block;font-size:12px;line-height:18px;color:var(--w-text-3);margin-top:2px}.w-plan-link{color:#5F1FE6;text-decoration:none;font-size:13px;font-weight:500;white-space:nowrap}
</style>
